/**
 * English interface copy — the accommodation, kept complete so the language toggle is real.
 *
 * Split out of i18n.js on 2026-09-27 with i18n.ar.js (see its header): a visit loads only the
 * dictionary of the language it is shown in. An English page falls back to the key itself
 * for a missing string; an Arabic page whose dictionary failed to load falls back to this
 * file, which `I18N.ready()` fetches in that case.
 *
 * Add a key here AND in i18n.ar.js, in the same group.
 */
