    'setup.metaTitle': 'In the Meta console — done by hand',
    'setup.metaWhy': 'There is no “Connect with Facebook” button here. An OAuth connect flow needs Advanced Access from Meta, which needs Business Verification and per-permission App Review — so the two steps below are done once, by you, in Meta’s own console.',
    'setup.metaStep1': 'Obtain a PAGE access token.',
    'setup.metaStep1Detail': 'In the Graph API Explorer: pick the app, choose “Get Page Access Token”, then exchange it for a long-lived one. It must be a PAGE token, not a USER token, and must carry the publishing, messaging and comment permissions.',
    'setup.metaStep2': 'Point the Meta webhook callback at this URL.',
    'setup.metaStep2Detail': 'Under Webhooks in the app settings: paste this as the Callback URL, and the verify token you are about to type below as the Verify Token.',
    'setup.metaStep3': 'Subscribe to the fields this app reads.',
    'setup.metaStep3Detail': 'For the instagram object: comments and messages. For the page object: feed and messages. Without them nothing arrives, and nothing anywhere reports an error.',
    'setup.hereTitle': 'Here',
    'setup.hereStep1': 'Create the tenant with its Instagram page ID (required) and its Facebook page ID.',
    'setup.hereStep1Detail': 'The ID is digits only. One wrong digit means every webhook for this tenant matches nothing and is dropped silently.',
    'setup.hereStep2': 'Paste the page access token, and the same verify token.',
